target.css:
:root {
  --ink: #263342;
  --muted: #687481;
  --paper: #fffdf7;
  --line: #d8d5c7;
  --night: #28394d;
  --cream: #f6eed7;
  --gold: #dda842;
  --gold-soft: #fff1bd;
  --mint: #dcefe4;
  --mint-ink: #28624c;
}

* {
  box-sizing: border-box;
}

.kit-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.kit-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  background: var(--night);
}

.emblem {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  font-size: 23px;
  background: var(--gold-soft);
  border-radius: 12px;
}

.heading {
  flex: 1;
}

.heading h1 {
  margin: 0;
  color: var(--paper);
  font-size: 18px;
  line-height: 1.2;
}

.heading p {
  margin: 3px 0 0;
  color: var(--cream);
  font-size: 12px;
}

.status {
  padding: 5px 8px;
  color: var(--mint-ink);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .06em;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.detail {
  margin: 0;
}

.detail span {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.detail strong {
  display: block;
  margin-top: 2px;
  font-size: 13px;
}

.checklist {
  display: grid;
  gap: 7px;
  margin: 0;
  padding: 12px 16px;
  list-style: none;
}

.checklist li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
}

.check {
  display: grid;
  width: 19px;
  height: 19px;
  place-items: center;
  color: var(--mint-ink);
  background: var(--mint);
  border-radius: 50%;
  font-size: 12px;
  font-weight: 800;
}

.note {
  margin: 0 16px;
  padding: 9px 11px;
  color: var(--ink);
  background: var(--cream);
  border-left: 3px solid var(--gold);
  border-radius: 0 8px 8px 0;
  font-size: 12px;
  line-height: 1.35;
}

.kit-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  color: var(--muted);
  font-size: 12px;
}

.kit-footer strong {
  color: var(--ink);
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--night);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

